class Solution {
    public List<List<Integer>> threeSum(int[] nums) {
        Arrays.sort(nums);
        Set<List<Integer>> res = new HashSet<>();
        for (int i = 0; i < nums.length; i++) {
            int x = nums[i];
            if (i > 0 && x == nums[i - 1]) {
                continue;
            }
            Set<Integer> seen = new HashSet<>();
            for (int j = i + 1; j < nums.length; j++) {
                int y = nums[j];
                if (seen.contains(-x - y)) {
                    res.add(Arrays.asList(x, -x - y, y));
                }
                seen.add(y);
            }
        }
        List<List<Integer>> out = new ArrayList<>(res);
        out.sort((a, b) -> !a.get(0).equals(b.get(0)) ? a.get(0) - b.get(0) : !a.get(1).equals(b.get(1)) ? a.get(1) - b.get(1) : a.get(2) - b.get(2));
        return out;
    }
}

