          seenIdx.push(j);
        }
      }
      res.sort((p, q) => p[0] - q[0] || p[1] - q[1] || p[2] - q[2]);
      seenIdx = [];
      snap("完成", `一共找到 <b>${res.length}</b> 组，排好序输出。`, view(-1, -1, -1), { at: "done", kind: "ok", ans: res });
